package com.ehtid.screentranslator;
import android.app.*;import android.os.*;import android.content.*;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 static final int CAPTURE=42; MediaProjectionManager mgr;
 @Override public void onCreate(Bundle b){super.onCreate(b);mgr=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(38,70,38,30);l.setBackgroundColor(0xff171226);TextView title=new TextView(this);title.setText("EHTID • SCREEN TRANSLATOR\n\nАвтоопределение языка → русский\nOCR + офлайн-перевод ML Kit\n\nПервый запуск скачает языковые модели.");title.setTextColor(-1);title.setTextSize(20);l.addView(title);Button btn=new Button(this);btn.setText("Запустить переводчик");l.addView(btn);btn.setOnClickListener(v->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION, Uri.parse("package:"+getPackageName())));Toast.makeText(this,"Разреши показ поверх приложений, затем вернись",Toast.LENGTH_LONG).show();return;}startActivityForResult(mgr.createScreenCaptureIntent(),CAPTURE);});Button stop=new Button(this);stop.setText("Остановить");l.addView(stop);stop.setOnClickListener(v->stopService(new Intent(this,CaptureService.class)));setContentView(l);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==CAPTURE&&c==RESULT_OK&&d!=null){Intent i=new Intent(this,CaptureService.class);i.putExtra("result",c);i.putExtra("data",d);startForegroundService(i);moveTaskToBack(true);}}
}